import pytest

from minerd.config import Config
from minerd.mockrun import build_engine, run_epoch
from minerd.signer import Signer

EPOCH = 29_860_000  # fixed epoch so runs are reproducible


@pytest.fixture(scope="session")
def cfg() -> Config:
    return Config.from_env()


@pytest.fixture(scope="session")
def device_address(cfg) -> str:
    return cfg.registration().device_address


def run(cfg, scenario="festival_smog", seed=1, drop=(), fake=()):
    engine, vision = build_engine(cfg, scenario, seed=seed)
    start = EPOCH * 60_000
    vision.faults.dropped = {t: start + 20_000 for t in drop}
    vision.faults.fake = set(fake)
    return engine, run_epoch(engine, vision, EPOCH)


@pytest.fixture(scope="session")
def smog(cfg):
    return run(cfg)


@pytest.fixture(scope="session")
def attestation(cfg, smog) -> dict:
    engine, result = smog
    return Signer(cfg.device_key()).sign(result.c3_unsigned(engine.cat.calibration_hash))

"""Everything miner-core emits must pass contracts-schema/scripts/validate.py."""

import json

from minerd.canonical import keccak_jcs
from minerd.contracts import errors
from minerd.mockrun import build_engine
from tests.conftest import EPOCH


def test_c3_attestation_valid(attestation):
    assert errors("c3-attestation", attestation) == []


def test_c2_epoch_valid_for_every_status(smog, attestation):
    _, result = smog
    base = {"evidence_hash": attestation["evidence_hash"], "amount": attestation["amount"]}
    for att in ({"status": "pending", **base}, {"status": "queued", **base}, {"status": "submitted", **base},
                {"status": "accepted", **base, "tx_hash": "0x" + "ab" * 32},
                {"status": "rejected", **base, "reason_code": "amount_over_cap", "reason": "too much"}):
        assert errors("c2-epoch", result.c2_epoch(att)) == [], att["status"]


def test_c2_telemetry_valid(cfg):
    engine, vision = build_engine(cfg, "rush_hour", seed=2)
    t0 = EPOCH * 60_000
    for i in range(15):
        engine.ingest_vision(vision.message(t0 + i * 1000), t0 + i * 1000)
        telemetry, _ = engine.tick(t0 + i * 1000)
        telemetry["uplink"] = {"online": True, "queued_attestations": 0}
        assert errors("c2-telemetry", telemetry) == [], i


def test_mock_vision_is_valid_c1(cfg):
    _, vision = build_engine(cfg, "clean_morning", seed=3)
    t0 = EPOCH * 60_000
    vision.faults.dropped = {4: t0}
    vision.faults.fake = {9}
    vision.faults.unknown_tags = {77}
    for t in (t0, t0 + 15_000, t0 + 70_000):
        assert errors("c1-vision-event", vision.message(t)) == []


def test_calibration_hash_is_catalogue_on_disk(cfg, attestation):
    doc = json.loads(cfg.catalogue_path.read_text(encoding="utf-8"))
    assert attestation["calibration_hash"] == keccak_jcs(doc)

from decimal import Decimal

import pytest

from tests.conftest import run


def by_tag(result):
    return {p["tag_id"]: p for p in result.plants}


def test_scenarios_order_by_pollution(cfg):
    air = {s: run(cfg, s)[1].total_air for s in ("rain_washout", "clean_morning", "rush_hour", "festival_smog")}
    assert air["rain_washout"] < air["clean_morning"] < air["rush_hour"] < air["festival_smog"]
    assert air["rain_washout"] > 0


def test_all_present_plants_paid(smog):
    _, result = smog
    assert len(result.plants) == 20
    assert all(p["status"] == "present" and p["air"] > 0 for p in result.plants)


def test_amount_is_total_in_base_units(smog):
    _, result = smog
    assert Decimal(result.amount) == int(result.total_air * 10**18)
    assert result.total_air == sum(Decimal(str(p["air"])) for p in result.plants)


def test_dropped_and_fake_plants_earn_nothing(cfg, smog):
    _, result = run(cfg, drop=[3], fake=[12])
    plants = by_tag(result)
    assert plants[3]["status"] == "missing"
    assert plants[12]["status"] == "suspect"
    for tag in (3, 12):
        assert plants[tag]["air"] == 0 and plants[tag]["removed_mg"] == {}
    assert result.total_air < smog[1].total_air
    codes = {(f["code"], f.get("tag_id")) for f in result.flags}
    assert ("plant_missing", 3) in codes and ("low_liveness", 12) in codes


def test_removed_plant_earns_nothing(cfg):
    engine, vision = __import__("minerd.mockrun", fromlist=["build_engine"]).build_engine(cfg, "rush_hour", seed=1)
    from minerd.mockrun import run_epoch
    from tests.conftest import EPOCH
    vision.faults.dropped = {5: EPOCH * 60_000}
    run_epoch(engine, vision, EPOCH)  # missing during this epoch, removed by the end of the next
    result = run_epoch(engine, vision, EPOCH + 1)
    p = by_tag(result)[5]
    assert p["status"] == "removed" and p["air"] == 0 and p["leaf_area_cm2"] == 0


@pytest.mark.parametrize("scenario", ["festival_smog", "rush_hour"])
def test_caps_hold(cfg, scenario):
    engine, result = run(cfg, scenario)
    cat = engine.cat
    assert all(p["air"] <= cat.per_plant_cap for p in result.plants)
    assert result.total_air <= Decimal(str(cat.per_miner_cap))


def test_caps_bind_when_rates_are_huge(cfg):
    engine, vision = __import__("minerd.mockrun", fromlist=["build_engine"]).build_engine(cfg, "festival_smog", seed=1)
    from minerd.mockrun import run_epoch
    from tests.conftest import EPOCH
    cat = engine.cat
    for species in cat.k:
        cat.k[species] = {p: v * 1e6 for p, v in cat.k[species].items()}
    result = run_epoch(engine, vision, EPOCH)
    assert all(p["air"] <= cat.per_plant_cap + 1e-9 for p in result.plants)
    assert result.total_air <= Decimal(str(cat.per_miner_cap))
    assert result.total_air > Decimal(str(cat.per_miner_cap)) * Decimal("0.99")


def test_same_inputs_same_attestation(cfg):
    a, b = run(cfg, seed=7)[1], run(cfg, seed=7)[1]
    assert a.plants == b.plants and a.total_air == b.total_air
